SELECT age_bucket, signup_year, age_range FROM (SELECT CASE WHEN age >= 65 THEN 'high' WHEN age >= 36 THEN 'mid' ELSE 'low' END AS age_bucket, YEAR(signup_date) AS signup_year, MAX(age) - MIN(age) AS age_range FROM customers WHERE country IN ('SG', 'US', 'TH') GROUP BY CASE WHEN age >= 65 THEN 'high' WHEN age >= 36 THEN 'mid' ELSE 'low' END, YEAR(signup_date)) AS x WHERE age_range < 23
